import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.server.level.ServerPlayer;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.api.distmarker.OnlyIn;

public class CheckmarkTask
extends AbstractBooleanTask {
    public CheckmarkTask(long id, Quest quest) {
        super(id, quest);
    }

    @Override
    public TaskType getType() {
        return TaskTypes.CHECKMARK;
    }

    @Override
    @OnlyIn(value=Dist.CLIENT)
    public void drawGUI(TeamData teamData, GuiGraphics graphics, int x, int y, int w, int h) {
        (teamData.isCompleted(this) ? (Icon)ThemeProperties.CHECKMARK_TASK_ACTIVE.get(this) : (Icon)ThemeProperties.CHECKMARK_TASK_INACTIVE.get(this)).draw(graphics, x, y, w, h);
    }

    @Override
    public boolean canSubmit(TeamData teamData, ServerPlayer player) {
        return true;
    }

    @Override
    public boolean checkOnLogin() {
        return false;
    }

    @Override
    protected boolean hasIconConfig() {
        return false;
    }
}

