    long max = this.getMaxProgress();
    if (max <= 0L) {
        return 0;
    }
    long progress = data.getProgress(this);
    if (progress <= 0L) {
        return 0;
    }
    if (progress >= max) {
        return 100;
    }
    return (int)Math.max(1.0, (double)progress * 100.0 / (double)max);
